#include "contract_test.h"
#include "activation_quantizer.h"
int main(){using namespace laya;QuantTask t;t.ctx=test::ctx(Op::QUANT,2,0,RowSpace::TOKEN,0,16);t.src=test::ref(Buffer::NORM);t.a_dst=test::ref(Buffer::A8);t.K=1024;uint32_t groups=0;test::require(activation_quantizer::validate(t,2,128,groups)&&groups==512,"16x1024 groups");t.input_lanes=4;test::require(!activation_quantizer::validate(t,2,128,groups),"F0 lane constraint");t.input_lanes=8;t.ctx=test::ctx(Op::QUANT,4,0);t.src=test::ref(Buffer::ATT_OUT);test::require(activation_quantizer::validate(t,2,128,groups),"Decision AV to Wo quant");t.ctx=test::ctx(Op::QUANT,6,255,RowSpace::TOKEN,0,16);t.K=4096;t.src=none();test::require(!activation_quantizer::validate(t,2,128,groups),"act task row space/source/K binding");}
